def merge_dictionaries(first_input_dictionary, second_input_dictionary):
    """
    Merges two dictionaries into a new dictionary.
    Values from the second dictionary override those from the first if keys overlap.
    """
    combined_dictionary_result = first_input_dictionary.copy()
    for key_from_second_dict, value_from_second_dict in second_input_dictionary.items():
        combined_dictionary_result[key_from_second_dict] = value_from_second_dict
    return combined_dictionary_result

