def is_valid_parentheses(input_string):
    opening_brackets = "([{"
    closing_brackets = ")]}"
    matching_bracket_map = {")": "(", "}": "{", "]": "["}
    character_stack = []

    for current_character in input_string:
        if current_character in opening_brackets:
            character_stack.append(current_character)
        elif current_character in closing_brackets:
            if not character_stack:
                return False
            last_opened_bracket = character_stack.pop()
            expected_opening_bracket = matching_bracket_map[current_character]
            if last_opened_bracket != expected_opening_bracket:
                return False
        else:
            # Should not happen based on problem description
            continue

    return len(character_stack) == 0

