def roman_to_int(roman_numeral_string):
    roman_value_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_result = 0
    previous_character_value = 0
    numeral_length = len(roman_numeral_string)

    for current_index in range(numeral_length - 1, -1, -1):
        current_roman_char = roman_numeral_string[current_index]
        current_character_value = roman_value_map[current_roman_char]

        if current_character_value < previous_character_value:
            integer_result -= current_character_value
        else:
            integer_result += current_character_value
        previous_character_value = current_character_value

    final_integer_value = integer_result
    return final_integer_value

