    }
    integerResult = 0
    previousCharacterValue = 0
    numeralLength = len(romanNumeralString)

    for currentIndex in range(numeralLength - 1, -1, -1):
        currentRomanChar = romanNumeralString[currentIndex]
        currentCharacterValue = romanValueMap[currentRomanChar]

        if currentCharacterValue < previousCharacterValue:
            integerResult -= currentCharacterValue
        else:
            integerResult += currentCharacterValue
        previousCharacterValue = currentCharacterValue

    finalIntegerValue = integerResult
