def is_valid_luhn(card_number_string):
    """
    Checks if a credit card number string is valid using a simplified Luhn algorithm.
    This version only performs the basic sum calculation.
    """
    digit_list = [int(digit_char) for digit_char in card_number_string]
    total_sum_of_digits = 0
    list_length = len(digit_list)

    for current_index_position in range(list_length - 1, -1, -1):
        current_digit_value = digit_list[current_index_position]

        if (list_length - 1 - current_index_position) % 2 == 1:
            doubled_digit_result = current_digit_value * 2
            if doubled_digit_result > 9:
                total_sum_of_digits += (doubled_digit_result - 9)
            else:
                total_sum_of_digits += doubled_digit_result
        else:
            total_sum_of_digits += current_digit_value

    final_luhn_check = (total_sum_of_digits % 10 == 0)
    return final_luhn_check

