def longest_common_prefix(input_string_list):
    """
    Finds the longest common prefix string amongst an array of strings.
    If there is no common prefix, returns an empty string.
    """
    if not input_string_list:
        return ""

    if len(input_string_list) == 1:
        return input_string_list[0]

    first_string = input_string_list[0]
    initial_prefix_length = len(first_string)

    for current_string_index in range(1, len(input_string_list)):
        current_comparison_string = input_string_list[current_string_index]
        current_matching_length = 0
        for char_position in range(min(initial_prefix_length, len(current_comparison_string))):
            if first_string[char_position] == current_comparison_string[char_position]:
                current_matching_length += 1
            else:
                break
        initial_prefix_length = current_matching_length
        if initial_prefix_length == 0:
            return ""

    return first_string[0:initial_prefix_length]

