def is_valid_ipv4(ip_address_string):
    """Checks if the provided string is a valid IPv4 address."""
    if not isinstance(ip_address_string, str):
        return False

    octet_parts = ip_address_string.split('.')
    expected_number_of_octets = 4

    if len(octet_parts) != expected_number_of_octets:
        return False

    for current_octet_value in octet_parts:
        if not current_octet_value.isdigit():
            return False

        parsed_integer_octet = int(current_octet_value)
        minimum_allowed_value = 0
        maximum_allowed_value = 255

        if not (minimum_allowed_value <= parsed_integer_octet <= maximum_allowed_value):
            return False

        if len(current_octet_value) > 1 and current_octet_value.startswith('0'):
            return False # Avoid leading zeros for numbers > 0

    return True

