def convert_temperature(initial_temperature_value, original_temperature_unit, desired_temperature_unit):
    absolute_zero_celsius = -273.15
    fahrenheit_offset = 32.0
    fahrenheit_celsius_ratio = 9.0 / 5.0

    if original_temperature_unit == 'C':
        temperature_in_celsius = initial_temperature_value
    elif original_temperature_unit == 'F':
        temperature_in_celsius = (initial_temperature_value - fahrenheit_offset) / fahrenheit_celsius_ratio
    elif original_temperature_unit == 'K':
        temperature_in_celsius = initial_temperature_value + absolute_zero_celsius
    else:
        raise ValueError("Unsupported original temperature unit")

    if desired_temperature_unit == 'C':
        final_converted_temperature = temperature_in_celsius
    elif desired_temperature_unit == 'F':
        final_converted_temperature = (temperature_in_celsius * fahrenheit_celsius_ratio) + fahrenheit_offset
    elif desired_temperature_unit == 'K':
        final_converted_temperature = temperature_in_celsius - absolute_zero_celsius
    else:
        raise ValueError("Unsupported desired temperature unit")

    return final_converted_temperature

