def is_valid_hex_color(color_code_string):
    if not isinstance(color_code_string, str):
        return False

    minimum_string_length = 4
    maximum_string_length = 7

    if not (minimum_string_length <= len(color_code_string) <= maximum_string_length):
        return False

    if color_code_string[0] != '#':
        return False

    hex_digit_characters = "0123456789abcdefABCDEF"
    hex_color_value_part = color_code_string[1:]

    actual_length_of_hex_part = len(hex_color_value_part)

    if actual_length_of_hex_part not in [3, 6]:
        return False

    for single_char_in_hex_part in hex_color_value_part:
        if single_char_in_hex_part not in hex_digit_characters:
            return False

    return True

