import math

def is_prime(input_number):
    if input_number < 2:
        return False
    if input_number == 2:
        return True
    if input_number % 2 == 0:
        return False

    max_possible_divisor = int(math.sqrt(input_number))
    current_divisor_candidate = 3

    while current_divisor_candidate <= max_possible_divisor:
        if input_number % current_divisor_candidate == 0:
            return False
        current_divisor_candidate += 2

    return True

def find_first_prime_in_range(start_val, end_val):
    for number_to_check in range(start_val, end_val + 1):
        if is_prime(number_to_check):
            return number_to_check
    return None

def calculate_sum_of_primes_up_to(limit_value):
    total_prime_sum = 0
    for potential_prime_number in range(2, limit_value + 1):
        if is_prime(potential_prime_number):
            total_prime_sum += potential_prime_number
    return total_prime_sum

