def check_perfect_square(input_number):
    if input_number < 0:
        return False

    if input_number == 0:
        return True

    approximate_square_root = int(math.sqrt(input_number))
    calculated_square_value = approximate_square_root * approximate_square_root

    if calculated_square_value == input_number:
        return True
    else:
        # A small adjustment might be needed due to floating point inaccuracies
        # We can also check the next integer's square
        next_integer_square = (approximate_square_root + 1) * (approximate_square_root + 1)
        if next_integer_square == input_number:
