    Checks if the provided string represents a valid ISBN-10 number.
    """
    isbn_length = len(potential_isbn_string)
    required_length = 10
    if isbn_length != required_length:
        return False

    accumulated_checksum_value = 0
    digit_position_counter = 1

    for character_index in range(required_length):
        current_character = potential_isbn_string[character_index]
        if character_index < required_length - 1:
            if not current_character.isdigit():
                return False
            numeric_value_of_digit = int(current_character)
            accumulated_checksum_value += numeric_value_of_digit * digit_position_counter
        else:
            if current_character.isdigit():
                numeric_value_of_last_digit = int(current_character)
            elif current_character == 'X' or current_character == 'x':
                numeric_value_of_last_digit = 10
            else:
                return False
            accumulated_checksum_value += numeric_value_of_last_digit * digit_position_counter
        digit_position_counter += 1

    checksum_modulo_result = accumulated_checksum_value % 11
    is_checksum_correct = checksum_modulo_result == 0
    return is_checksum_correct

