def obtain_quadrant_location(x_coordinate_value, y_coordinate_value):
    """
    Determines the quadrant of a point (x, y) in a 2D Cartesian system.
    Returns 1, 2, 3, or 4 for the quadrants, or 0 if on an axis.
    """
    if x_coordinate_value == 0 or y_coordinate_value == 0:
        return 0  # Point lies on an axis

    if x_coordinate_value > 0 and y_coordinate_value > 0:
        return 1  # First quadrant
    elif x_coordinate_value < 0 and y_coordinate_value > 0:
        return 2  # Second quadrant
    elif x_coordinate_value < 0 and y_coordinate_value < 0:
        return 3  # Third quadrant
    else:  # x_coordinate_value > 0 and y_coordinate_value < 0
        return 4  # Fourth quadrant

def calculate_point_region(first_input_x, second_input_y):
    result_quadrant_identifier = obtain_quadrant_location(first_input_x, second_input_y)
    return result_quadrant_identifier

