def fetch_quadrant(input_x_point, input_y_point):
    returned_value_for_quadrant = process_coordinates(input_x_point, input_y_point)
    return returned_value_for_quadrant

def get_quadrant(x_val, y_val):
    specific_result = fetch_quadrant(x_val, y_val)
