def censor_text(source_text_content, words_to_censor_list):
    processed_word_list = []
    text_words_split_by_space = source_text_content.split(' ')

    for current_word_from_text in text_words_split_by_space:
        cleaned_word_without_punctuation = current_word_from_text.strip('.,!?;:')
        original_word_length = len(current_word_from_text)

        is_word_found_in_bad_list = False
        for current_bad_entry in words_to_censor_list:
            if cleaned_word_without_punctuation.lower() == current_bad_entry.lower():
                processed_word_list.append('*' * original_word_length)
                is_word_found_in_bad_list = True
                break

        if not is_word_found_in_bad_list:
            processed_word_list.append(current_word_from_text)

    final_output_string_result = ' '.join(processed_word_list)
    return final_output_string_result

