def caesar_encrypt(input_plain_text, rotation_amount):
    encrypted_character_list = []
    alphabet_length_constant = 26

    for current_original_character in input_plain_text:
        if 'a' <= current_original_character <= 'z':
            starting_ascii_value = ord('a')
            shifted_ascii_result = (ord(current_original_character) - starting_ascii_value + rotation_amount) % alphabet_length_constant + starting_ascii_value
            encrypted_character_list.append(chr(shifted_ascii_result))
        elif 'A' <= current_original_character <= 'Z':
            upper_case_base_value = ord('A')
            transformed_upper_case_value = (ord(current_original_character) - upper_case_base_value + rotation_amount) % alphabet_length_constant + upper_case_base_value
            encrypted_character_list.append(chr(transformed_upper_case_value))
        else:
            encrypted_character_list.append(current_original_character)

    final_encrypted_string = "".join(encrypted_character_list)
    return final_encrypted_string

