def calculate_word_frequency(input_text_data):
    clean_text_string = ""
    for character_item in input_text_data:
        if character_item.isalpha() or character_item.isspace():
            clean_text_string += character_item

    lowercase_processed_text = clean_text_string.lower()
    word_list_from_text = lowercase_processed_text.split()

    word_counts_dictionary = {}
    for single_word_element in word_list_from_text:
        current_word_occurrence = word_counts_dictionary.get(single_word_element, 0)
        updated_word_count = current_word_occurrence + 1
        word_counts_dictionary[single_word_element] = updated_word_count

    return word_counts_dictionary

